svg.script:
let svg = null;
let layer1 = null;
let regions = null;
let circles = null;
let controls = null;
let purple_senators = null;
let green_senators = null;

function load_all() {
    if (svg === null) {
        svg = document.getElementById("svg1");
        layer1 = document.getElementById("layer1");

        regions = [
            [document.getElementById("region1"), document.getElementById("text1")],
            [document.getElementById("region2"), document.getElementById("text2")],
            [document.getElementById("region3"), document.getElementById("text3")],
            [document.getElementById("region4"), document.getElementById("text4")],
            [document.getElementById("region5"), document.getElementById("text5")],
            [document.getElementById("region6"), document.getElementById("text6")],
            [document.getElementById("region7"), document.getElementById("text7")],
            [document.getElementById("region8"), document.getElementById("text8")],
            [document.getElementById("region9"), document.getElementById("text9")],
        ];
        circles = Array.from(document.querySelectorAll("circle:not([id^='control'])"));

        controls = Array.from(document.querySelectorAll("circle[id^='control']"));
        controls.forEach(control => {
            control.addEventListener("mousedown", start_drag);
            control.addEventListener("touchstart", start_drag);
        });

        purple_senators = document.getElementById("purple_senators");
        green_senators = document.getElementById("green_senators");
    }
}

function vertices(region) {
    const d = region.getAttribute("d");
    const regex = /[ML]\s*(-?\d+(\.\d+)?),?\s*(-?\d+(\.\d+)?)/g;
    let match;
    const nodes = [];

    while ((match = regex.exec(d)) !== null) {
        const x = parseFloat(match[1]);
        const y = parseFloat(match[3]);
        nodes.push([x, y]);
    }

    return nodes;
}

function points(circles) {
    return circles.map(circle => {
        const x = parseFloat(circle.getAttribute("cx"));
        const y = parseFloat(circle.getAttribute("cy"));
        const is_purple = circle.id.startsWith("purple");
        return [x, y, is_purple];
    });
}

function point_inside(x, y, vertices) {
    let is_inside = false;
    for (let i = 0, j = vertices.length - 1;  i < vertices.length;  j = i++) {
        const [xi, yi] = vertices[i];
        const [xj, yj] = vertices[j];
        if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) {
            is_inside = !is_inside;
        }
    }
    return is_inside;
}

function count_inside(points, vertices) {
    let num_purple = 0;
    let num_green = 0;
    points.forEach(([x, y, is_purple]) => {
        if (point_inside(x, y, vertices)) {
            if (is_purple) {
                num_purple++;
            }
            else {
                num_green++;
            }
        }
    });
  return [num_purple, num_green];
}

function centroid(vertices) {
    let x_sum = 0, y_sum = 0;
    let A = 0;

    for (let i = 0; i < vertices.length; i++) {
        const [x0, y0] = vertices[i];
        const [x1, y1] = vertices[(i + 1) % vertices.length];

        const cross_product = x0 * y1 - x1 * y0;
        A += cross_product;
        x_sum += (x0 + x1) * cross_product;
        y_sum += (y0 + y1) * cross_product;
    }

    A *= 0.5;
    const centroidX = x_sum / (6 * A);
    const centroidY = y_sum / (6 * A);

    return [centroidX, centroidY];
}

function do_segments_intersect(p1, q1, p2, q2) {
    function orientation(p, q, r) {
        const val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1]);
        if (val === 0) return 0;  // collinear
        return (val > 0) ? 1 : 2; // clockwise or counterclockwise
    }

    function onSegment(p, q, r) {
        return q[0] <= Math.max(p[0], r[0]) && q[0] >= Math.min(p[0], r[0]) &&
               q[1] <= Math.max(p[1], r[1]) && q[1] >= Math.min(p[1], r[1]);
    }

    const o1 = orientation(p1, q1, p2);
    const o2 = orientation(p1, q1, q2);
    const o3 = orientation(p2, q2, p1);
    const o4 = orientation(p2, q2, q1);

    // general case
    if (o1 !== o2 && o3 !== o4) return true;

    // special cases
    if (o1 === 0 && onSegment(p1, p2, q1)) return true;
    if (o2 === 0 && onSegment(p1, q2, q1)) return true;
    if (o3 === 0 && onSegment(p2, p1, q2)) return true;
    if (o4 === 0 && onSegment(p2, q1, q2)) return true;

    return false; // doesn't fall in any of the above cases
}

function is_simple_polygon(vertices) {
    const n = vertices.length;
    for (let i = 0; i < n; i++) {
        const p1 = vertices[i];
        const q1 = vertices[(i + 1) % n];

        for (let j = i + 1; j < n; j++) {
            if (j === (i + 1) % n || (i === 0 && j === n - 1)) {
                // skip adjacent edges
                continue;
            }

            const p2 = vertices[j];
            const q2 = vertices[(j + 1) % n];

            if (do_segments_intersect(p1, q1, p2, q2)) {
                return false;
            }
        }
    }
    return true;
}

function update_count() {
    load_all();

    let purple_count = 0;
    let green_count = 0;

    regions.forEach(([region, text]) => {
        let [num_purple, num_green] = count_inside(points(circles), vertices(region));
        text.firstChild.textContent = num_purple.toString() + " purple";
        text.lastChild.textContent = num_green.toString() + " green";
        let color;
        if (num_purple > num_green) {
            color = "#ff1dff";
            purple_count++;
        }
        else {
            color = "#09ff20";
            green_count++;
        }
        text.style.fill = color;
        text.firstChild.style.fill = color;
        text.lastChild.style.fill = color;
    });

    purple_senators.textContent = purple_count.toString() + " purple senators";
    green_senators.textContent = green_count.toString() + " green senators";
}

let control = null;
let control_offset = {x: 0, y: 0};
let constraint = "";
let moving = [];
let region = null;
let region_vertices = null;
let region_node = 0;
let node_offset = {x: 0, y: 0};

function start_drag(event) {
    control = event.target;
    control_offset = mouse_position(event);
    let offset_x = control_offset.x;
    let offset_y = control_offset.y;

    const cx = parseFloat(control.getAttributeNS(null, "cx"));
    const cy = parseFloat(control.getAttributeNS(null, "cy"));
    control_offset.x -= cx;
    control_offset.y -= cy;

    moving = control.getAttribute("inkscape:label").split(" ").map(spec => {
        if (spec == "X"  ||  spec == "Y"  ||  spec == "B") {
            constraint = spec;
        }
        else {
            let [region, node] = spec.split(":");
            let [r, t] = regions[parseInt(region)]
            let v = vertices(r)
            let n = parseInt(node);
            return {
                region: r,
                text: t,
                vertices: v,
                node: n,
                offset: [offset_x - v[n][0], offset_y - v[n][1]],
            };
        }
    });
    moving.shift();

    const [region, node] = control.getAttribute("inkscape:label").split(":");

    document.addEventListener("mousemove", drag);
    document.addEventListener("touchmove", drag, {passive: false});
    document.addEventListener("mouseup", end_drag);
    document.addEventListener("touchend", end_drag);

    event.preventDefault();
}

function vertices_to_path(vertices) {
    const segments = [`M ${vertices[0][0]},${vertices[0][1]}`];
    for (let i = 1;  i < vertices.length;  i++) {
        const [x, y] = vertices[i];
        segments.push(`L ${x},${y}`);
    }
    segments.push("Z");
   return segments.join(' ');
}

function update(vertices, node, x, y) {
    if (constraint == "B"  ||  constraint == "X") {
        vertices[node][0] = x;
    }
    if (constraint == "B"  ||  constraint == "Y") {
        vertices[node][1] = y;
    }
}

function drag(event) {
    if (control) {
        event.preventDefault();
        const coord = mouse_position(event);

        const all_simple = moving.reduce((so_far, obj) => {
            const vertices = obj.vertices.slice();
            update(vertices, obj.node, coord.x - obj.offset[0], coord.y - obj.offset[1]);
            return so_far  &&  is_simple_polygon(vertices);
        }, true);

        if (all_simple) {
            if (constraint == "B"  ||  constraint == "X") {
                control.setAttributeNS(null, "cx", coord.x - control_offset.x);
            }
            if (constraint == "B"  ||  constraint == "Y") {
                control.setAttributeNS(null, "cy", coord.y - control_offset.y);
            }

            moving.forEach(obj => {
                update(obj.vertices, obj.node, coord.x - obj.offset[0], coord.y - obj.offset[1]);
                obj.region.setAttribute("d", vertices_to_path(obj.vertices));

                let [x, y] = centroid(obj.vertices);
                x -= 0.04823305;
                y -= 2.5567008;
                obj.text.setAttribute("x", x);
                obj.text.setAttribute("y", y);
                obj.text.firstChild.setAttribute("x", x);
                obj.text.firstChild.setAttribute("y", y);
                y += 9.0167;
                obj.text.lastChild.setAttribute("x", x);
                obj.text.lastChild.setAttribute("y", y);
            });

            update_count();
        }
    }
}

function end_drag() {
    if (control) {
        control = null;
        moving = [];
        document.removeEventListener("mousemove", drag);
        document.removeEventListener("touchmove", drag);
        document.removeEventListener("mouseup", end_drag);
        document.removeEventListener("touchend", end_drag);
    }
}

function mouse_position(event) {
    const point = svg.createSVGPoint();

    if (event.touches) {
        point.x = event.touches[0].clientX;
        point.y = event.touches[0].clientY;
    } else {
        point.x = event.clientX;
        point.y = event.clientY;
    }

    const ctm = layer1.getScreenCTM().inverse();
    return point.matrixTransform(ctm);
}

document.addEventListener("DOMContentLoaded", update_count);
